//! Offline tests for the iTIP routes: the router is driven directly, the mail is
//! served by a fake IMAP server, the calendar by a fake CalDAV server and the
//! reply by a fake SMTP server. No network, no real server.
//!
//! The daemon refuses a plaintext session for stored credentials, so both mail
//! fakes speak TLS with a certificate generated by `openssl` for the test and
//! trusted through `TlsOptions`.

use std::fs;
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex, OnceLock};

use axum::body::{Body, Bytes};
use axum::http::{Request, StatusCode};
