use lavande_mail::tls::TlsOptions;
use lavande_mail_api::app;
use lavande_mail_api::secrets::SecretBackend;
use lavande_mail_api::state::AppState;
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, PrivateKeyDer};
use serde_json::{json, Value};
use tempfile::TempDir;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio_rustls::TlsAcceptor;
use tower::ServiceExt;

const INVITATION_ICS: &str = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Zimbra//FR\r\n\
     METHOD:REQUEST\r\nBEGIN:VEVENT\r\nUID:reunion-42\r\nSUMMARY:Revue de design\r\n\
     DTSTART;TZID=Europe/Paris:20261125T140000\r\nDTEND;TZID=Europe/Paris:20261125T150000\r\n\
     SEQUENCE:3\r\nORGANIZER;CN=Camille Roy:mailto:camille@studio-lilas.fr\r\n\
     ATTENDEE;PARTSTAT=NEEDS-ACTION;RSVP=TRUE:mailto:roman@lavande.mail\r\n\
     END:VEVENT\r\nEND:VCALENDAR\r\n";

/// One RFC 5322 message carrying the invitation as a `text/calendar` part.
fn message() -> String {
    format!(
        "From: Camille Roy <camille@studio-lilas.fr>\r\n\
         To: Roman <roman@lavande.mail>\r\n\
         Subject: Revue de design\r\n\
         Date: Tue, 10 Nov 2026 11:02:00 +0100\r\n\
         Message-ID: <invitation-42@studio-lilas.fr>\r\n\
         MIME-Version: 1.0\r\n\
         Content-Type: multipart/mixed; boundary=\"sep\"\r\n\
         \r\n\
         --sep\r\n\
         Content-Type: text/plain; charset=utf-8\r\n\
         \r\n\
         Tu viens ?\r\n\
         --sep\r\n\
         Content-Type: text/calendar; charset=utf-8; method=REQUEST\r\n\
         Content-Disposition: attachment; filename=\"invitation.ics\"\r\n\
         \r\n\
         {INVITATION_ICS}\
         --sep--\r\n"
    )
}

/// TLS material of the fakes: the temporary directory holding it, the
/// certificate and its key.
struct Material {
    _directory: TempDir,
    certificate: Vec<u8>,
    key: Vec<u8>,
}

/// Certificate of the fakes, generated once for the whole test binary. `None`
/// when `openssl` is missing: the scenarios are then skipped instead of failing
/// on an environment the daemon refuses (plaintext with stored credentials).
fn tls_material() -> Option<&'static Material> {
    static MATERIAL: OnceLock<Option<Material>> = OnceLock::new();
    MATERIAL
        .get_or_init(|| {
            let directory = tempfile::tempdir().ok()?;
            let cert = directory.path().join("cert.pem");
            let key = directory.path().join("key.pem");
            let status = Command::new("openssl")
                .args([
                    "req",
                    "-x509",
                    "-newkey",
                    "rsa:2048",
                    "-nodes",
                    "-days",
                    "2",
                    "-subj",
                    "/CN=localhost",
                    "-addext",
                    "subjectAltName=DNS:localhost,IP:127.0.0.1",
                    "-addext",
                    "basicConstraints=critical,CA:FALSE",
                    "-addext",
                    "keyUsage=critical,digitalSignature,keyEncipherment",
                    "-addext",
                    "extendedKeyUsage=serverAuth",
                    "-keyout",
                    key.to_str()?,
                    "-out",
                    cert.to_str()?,
                ])
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status()
                .ok()?;
            if !status.success() {
                return None;
            }
            Some(Material {
                _directory: directory,
                certificate: fs::read(&cert).ok()?,
                key: fs::read(&key).ok()?,
            })
        })
        .as_ref()
}

fn tls_options() -> TlsOptions {
    let material = tls_material().expect("certificat de test");
    TlsOptions {
        extra_roots_pem: vec![material.certificate.clone()],
    }
}

fn acceptor() -> TlsAcceptor {
    let material = tls_material().expect("certificat de test");
    let certificates: Vec<CertificateDer<'static>> =
        CertificateDer::pem_slice_iter(&material.certificate)
            .filter_map(Result::ok)
            .collect();
    let key = PrivateKeyDer::from_pem_slice(&material.key).expect("clé privée de test");
    let config = rustls::ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(certificates, key)
        .expect("configuration TLS de test");
    TlsAcceptor::from(Arc::new(config))
}

/// Fake IMAP server serving one message: greeting, LOGIN, SELECT and the
/// `UID FETCH` of the raw message.
async fn serve_imap(raw: String) -> u16 {
    let acceptor = acceptor();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("écoute IMAP");
    let port = listener.local_addr().expect("adresse locale").port();
    tokio::spawn(async move {
        while let Ok((socket, _)) = listener.accept().await {
            let acceptor = acceptor.clone();
            let raw = raw.clone();
            tokio::spawn(async move {
                let Ok(mut socket) = acceptor.accept(socket).await else {
                    return;
                };
                let _ = socket
                    .write_all(b"* OK [CAPABILITY IMAP4rev1] Lavande fake IMAP\r\n")
                    .await;
                let mut buffer = Vec::new();
                let mut chunk = [0u8; 4096];
                loop {
                    let read = match socket.read(&mut chunk).await {
                        Ok(0) | Err(_) => break,
                        Ok(read) => read,
                    };
                    buffer.extend_from_slice(&chunk[..read]);
                    while let Some(end) = buffer.windows(2).position(|pair| pair == b"\r\n") {
                        let line = String::from_utf8_lossy(&buffer[..end]).to_string();
                        buffer.drain(..end + 2);
                        let mut parts = line.split_whitespace();
                        let tag = parts.next().unwrap_or_default().to_string();
                        let command = parts.next().unwrap_or_default().to_ascii_uppercase();
                        let answer = match command.as_str() {
                            "LOGIN" => format!("{tag} OK LOGIN completed\r\n"),
                            "SELECT" | "EXAMINE" => format!(
                                "* 1 EXISTS\r\n* OK [UIDVALIDITY 1]\r\n\
                                 * OK [UIDNEXT 2]\r\n{tag} OK SELECT completed\r\n"
                            ),
                            "UID" => format!(
                                "* 1 FETCH (BODY[] {{{}}}\r\n{raw})\r\n\
                                 {tag} OK FETCH completed\r\n",
                                raw.len()
                            ),
                            "LOGOUT" => format!("* BYE\r\n{tag} OK LOGOUT completed\r\n"),
                            _ => format!("{tag} OK done\r\n"),
                        };
                        let _ = socket.write_all(answer.as_bytes()).await;
                    }
                }
            });
        }
    });
    port
}

/// Fake CalDAV server holding one resource: the GET returns it with an ETag, the
/// PUT is recorded and answered with `status`.
async fn serve_caldav(
    resource: &'static str,
    seen: Arc<Mutex<Vec<String>>>,
    status: &'static str,
) -> String {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("écoute CalDAV");
    let address = listener.local_addr().expect("adresse locale");
    tokio::spawn(async move {
        while let Ok((mut socket, _)) = listener.accept().await {
            let seen = seen.clone();
            tokio::spawn(async move {
                let mut buffer = Vec::new();
                let mut chunk = [0u8; 4096];
                let mut length = 0usize;
                let mut head = None;
                while let Ok(read) = socket.read(&mut chunk).await {
                    if read == 0 {
                        break;
                    }
                    buffer.extend_from_slice(&chunk[..read]);
                    let text = String::from_utf8_lossy(&buffer).to_string();
                    if head.is_none() {
                        if let Some(end) = text.find("\r\n\r\n") {
                            length = text[..end]
                                .lines()
                                .find_map(|line| {
                                    let (name, value) = line.split_once(':')?;
                                    name.eq_ignore_ascii_case("content-length")
                                        .then(|| value.trim().parse::<usize>().ok())?
                                })
                                .unwrap_or(0);
                            head = Some(end + 4);
                        }
                    }
                    if let Some(start) = head {
                        if buffer.len() >= start + length {
                            break;
                        }
                    }
                }
                let request = String::from_utf8_lossy(&buffer).to_string();
                let method = request
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .split_whitespace()
                    .next()
                    .unwrap_or_default()
                    .to_string();
                seen.lock().expect("trace").push(request);
                let response = match method.as_str() {
                    "PUT" => format!("HTTP/1.1 {status}\r\nContent-Length: 0\r\n\r\n"),
                    _ => format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: text/calendar\r\nETag: \"7\"\r\n\
                         Content-Length: {}\r\n\r\n{resource}",
                        resource.len()
                    ),
                };
                let _ = socket.write_all(response.as_bytes()).await;
                let _ = socket.shutdown().await;
            });
        }
    });
    format!("http://{address}/dav/")
}

/// Fake SMTP server over implicit TLS: answers the submission and keeps what it
/// received, one line per entry, `__done__` once the message is complete.
async fn serve_smtp(seen: Arc<Mutex<Vec<String>>>) -> u16 {
    let acceptor = acceptor();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("écoute SMTP");
    let port = listener.local_addr().expect("adresse locale").port();
    tokio::spawn(async move {
        while let Ok((socket, _)) = listener.accept().await {
            let acceptor = acceptor.clone();
            let seen = seen.clone();
            tokio::spawn(async move {
                let Ok(mut socket) = acceptor.accept(socket).await else {
                    return;
                };
                let _ = socket.write_all(b"220 lavande.test ESMTP\r\n").await;
                let mut buffer = Vec::new();
                let mut chunk = [0u8; 4096];
                let mut data = false;
                loop {
                    let read = match socket.read(&mut chunk).await {
                        Ok(0) | Err(_) => break,
                        Ok(read) => read,
                    };
                    buffer.extend_from_slice(&chunk[..read]);
                    while let Some(end) = buffer.windows(2).position(|pair| pair == b"\r\n") {
                        let line = String::from_utf8_lossy(&buffer[..end]).to_string();
                        buffer.drain(..end + 2);
                        if data {
                            if line == "." {
                                data = false;
                                seen.lock().expect("trace").push("__done__".to_string());
                                let _ = socket.write_all(b"250 2.0.0 queued\r\n").await;
                            } else {
                                seen.lock().expect("trace").push(line);
                            }
                            continue;
                        }
                        seen.lock().expect("trace").push(line.clone());
                        let command = line
                            .split_whitespace()
                            .next()
                            .unwrap_or_default()
                            .to_ascii_uppercase();
                        let answer = match command.as_str() {
                            "EHLO" | "HELO" => {
                                "250-lavande.test\r\n250-AUTH PLAIN LOGIN\r\n250 8BITMIME\r\n"
                            }
                            "AUTH" => "235 2.7.0 authentication accepted\r\n",
                            "MAIL" | "RCPT" => "250 2.1.0 ok\r\n",
                            "DATA" => {
                                data = true;
                                "354 go ahead\r\n"
                            }
                            "QUIT" => "221 2.0.0 bye\r\n",
                            _ => "250 2.0.0 ok\r\n",
                        };
                        let _ = socket.write_all(answer.as_bytes()).await;
                    }
                }
            });
        }
    });
    port
}

fn account(imap_port: u16, smtp_port: u16) -> Value {
    json!({
        "id": "perso",
        "label": "Perso",
        "email": "roman@lavande.mail",
        "username": "roman@lavande.mail",
        "imap": { "host": "127.0.0.1", "port": imap_port, "encryption": "tls" },
        "smtp": { "host": "127.0.0.1", "port": smtp_port, "encryption": "tls" },
        "auth": { "kind": "password", "password": "secret" }
    })
}

async fn state_in(directory: &Path) -> Arc<AppState> {
    Arc::new(
        AppState::open_with(
            directory,
            tls_options(),
            Default::default(),
            SecretBackend::File,
        )
        .await
        .expect("état"),
    )
}

/// Seeds one stored message so the route finds it, as a sync would have.
fn seed_message(state: &Arc<AppState>) {
    use lavande_mail::model::{Address, AttachmentMeta, Flags, Message};
    let message = Message {
        account_id: "perso".to_string(),
        folder_path: "INBOX".to_string(),
        uid: 1,
        uidvalidity: 1,
        thread_id: "t-invitation".to_string(),
        message_id: Some("<invitation-42@studio-lilas.fr>".to_string()),
        in_reply_to: None,
        references: Vec::new(),
        from: Address {
            name: Some("Camille Roy".to_string()),
            email: "camille@studio-lilas.fr".to_string(),
        },
        to: vec![Address {
            name: None,
            email: "roman@lavande.mail".to_string(),
        }],
        cc: Vec::new(),
        subject: "Revue de design".to_string(),
        date: chrono::TimeZone::with_ymd_and_hms(&chrono::Utc, 2026, 11, 10, 10, 2, 0).single(),
        flags: Flags {
            unread: true,
            ..Flags::default()
        },
        size: 2048,
        pgp: PgpState::None,
        pgp_detail: None,
        preview: "Tu viens ?".to_string(),
        body_text: Some("Tu viens ?".to_string()),
        body_html: None,
        attachments: vec![AttachmentMeta {
            filename: "invitation.ics".to_string(),
            mime: "text/calendar".to_string(),
            size: 300,
            inline: false,
        }],
    };
    state
        .store()
        .upsert_message_with_attachment(&message, true)
        .expect("message rangé");
    state
        .store()
        .set_body(
            "perso",
            "INBOX",
            1,
            &lavande_mail::ParsedMessage {
                subject: "Revue de design".to_string(),
                from: message.from.clone(),
                to: message.to.clone(),
                cc: Vec::new(),
                date: message.date,
                message_id: message.message_id.clone(),
                in_reply_to: None,
                references: Vec::new(),
                body_text: Some("Tu viens ?".to_string()),
                body_html: None,
                attachments: message.attachments.clone(),
                pgp: PgpState::None,
                pgp_detail: None,
                preview: "Tu viens ?".to_string(),
            },
        )
        .expect("corps rangé");
}

async fn call(state: &Arc<AppState>, mut request: Request<Body>) -> (StatusCode, Bytes) {
    if !request.headers().contains_key("authorization") {
        request.headers_mut().insert(
            "authorization",
            format!("Bearer {}", state.token())
                .parse()
                .expect("en-tête"),
        );
    }
    let response = app(state.clone())
        .oneshot(request)
        .await
        .expect("le routeur répond");
    let status = response.status();
    let body = axum::body::to_bytes(response.into_body(), 1 << 20)
        .await
        .expect("corps de la réponse");
    (status, body)
}

fn json_of(body: &Bytes) -> Value {
    serde_json::from_slice(body).expect("corps JSON")
}

const INVITATION_URI: &str = "/api/accounts/perso/folders/INBOX/messages/1/invitation";
const RSVP_URI: &str = "/api/accounts/perso/folders/INBOX/messages/1/invitation/rsvp";

fn get(uri: &str) -> Request<Body> {
    Request::builder()
        .uri(uri)
        .body(Body::empty())
        .expect("requête")
}

fn rsvp(status: &str) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri(RSVP_URI)
        .header("content-type", "application/json")
        .body(Body::from(json!({ "status": status }).to_string()))
        .expect("requête")
}

/// One scenario: the fakes, the seeded account and the state the router reads.
/// `None` when the test certificate could not be generated.
struct Scenario {
    _directory: TempDir,
    state: Arc<AppState>,
    caldav: Arc<Mutex<Vec<String>>>,
    mails: Arc<Mutex<Vec<String>>>,
}

impl Scenario {
    async fn open(raw: String, with_calendar: bool) -> Option<Self> {
        Self::open_calendar(raw, with_calendar.then_some(INVITATION_ICS)).await
    }

    /// Same, with the resource the calendar server holds: `None` for an account
    /// with no CalDAV source at all.
    async fn open_calendar(raw: String, resource: Option<&'static str>) -> Option<Self> {
        if tls_material().is_none() {
            eprintln!("openssl absent : scénario iTIP sauté");
            return None;
        }
        let mails = Arc::new(Mutex::new(Vec::new()));
        let caldav = Arc::new(Mutex::new(Vec::new()));
        let imap = serve_imap(raw).await;
        let smtp = serve_smtp(mails.clone()).await;
        let url = match resource {
            Some(resource) => Some(serve_caldav(resource, caldav.clone(), "204 No Content").await),
            None => None,
        };
        let directory = tempfile::tempdir().expect("répertoire temporaire");
        fs::write(
            directory.path().join("accounts.json"),
            serde_json::to_vec_pretty(&[account(imap, smtp)]).expect("json"),
        )
        .expect("accounts.json");
        if let Some(url) = url {
            let sources = json!([{
                "id": "agenda",
                "name": "Agenda",
                "url": url,
                "calendar_href": "/dav/roman/Calendar/",
                "account_id": "perso"
            }]);
            fs::write(
                directory.path().join("calendars.json"),
                serde_json::to_vec_pretty(&sources).expect("json"),
            )
            .expect("calendars.json");
        }
        let state = state_in(directory.path()).await;
        seed_message(&state);
        Some(Self {
            _directory: directory,
            state,
            caldav,
            mails,
        })
    }
}

#[tokio::test]
async fn the_invitation_of_a_message_is_read() {
    let Some(scenario) = Scenario::open(message(), false).await else {
        return;
    };

    let (status, body) = call(&scenario.state, get(INVITATION_URI)).await;

    assert_eq!(status, StatusCode::OK, "{body:?}");
    let invitation = json_of(&body);
    assert_eq!(invitation["method"], "REQUEST");
    assert_eq!(invitation["uid"], "reunion-42");
    assert_eq!(invitation["summary"], "Revue de design");
    assert_eq!(invitation["date"], "2026-11-25");
    assert_eq!(invitation["start"], "14:00");
    assert_eq!(invitation["end"], "15:00");
    assert_eq!(invitation["all_day"], false);
    assert_eq!(invitation["timezone"], "Europe/Paris");
    assert_eq!(invitation["sequence"], 3);
    assert_eq!(invitation["organizer"]["email"], "camille@studio-lilas.fr");
    assert_eq!(invitation["organizer"]["name"], "Camille Roy");
    assert_eq!(invitation["attendees"][0]["email"], "roman@lavande.mail");
    assert_eq!(invitation["attendees"][0]["partstat"], "NEEDS-ACTION");
}

#[tokio::test]
async fn a_message_without_a_calendar_part_has_no_invitation() {
    let plain = "From: camille@studio-lilas.fr\r\nSubject: Bonjour\r\n\
         Content-Type: text/plain; charset=utf-8\r\n\r\nSalut.\r\n"
        .to_string();
    let Some(scenario) = Scenario::open(plain, false).await else {
        return;
    };

    let (status, body) = call(&scenario.state, get(INVITATION_URI)).await;

    assert_eq!(status, StatusCode::OK, "{body:?}");
    assert_eq!(json_of(&body), Value::Null);
}

#[tokio::test]
async fn an_answered_invitation_is_written_into_the_calendar() {
    let Some(scenario) = Scenario::open(message(), true).await else {
        return;
    };

    let (status, body) = call(&scenario.state, rsvp("ACCEPTED")).await;

    assert_eq!(status, StatusCode::OK, "{body:?}");
    let answer = json_of(&body);
    assert_eq!(answer["via"], "caldav");
    assert_eq!(answer["invitation"]["attendees"][0]["partstat"], "ACCEPTED");
    let requests = scenario.caldav.lock().expect("trace").clone();
    let put = requests
        .iter()
        .find(|request| request.starts_with("PUT "))
        .expect("PUT reçu");
    assert!(
        put.starts_with("PUT /dav/roman/Calendar/reunion-42.ics "),
        "{put}"
    );
    assert!(
        put.to_ascii_lowercase().contains("if-match: \"7\""),
        "{put}"
    );
    assert!(put.contains("PARTSTAT=ACCEPTED"), "{put}");
    // La ressource entière survit : l'organisateur, la séquence, le METHOD.
    assert!(
        put.contains("ORGANIZER;CN=Camille Roy:mailto:camille@studio-lilas.fr"),
        "{put}"
    );
    assert!(put.contains("SEQUENCE:3"), "{put}");
    assert!(put.contains("METHOD:REQUEST"), "{put}");
    // Rien n'est parti par mail : le serveur relaie la réponse.
    assert!(!scenario
        .mails
        .lock()
        .expect("trace")
        .contains(&"__done__".to_string()));
}

#[tokio::test]
async fn without_a_calendar_the_reply_is_mailed_to_the_organizer() {
    let Some(scenario) = Scenario::open(message(), false).await else {
        return;
    };

    let (status, body) = call(&scenario.state, rsvp("TENTATIVE")).await;

    assert_eq!(status, StatusCode::OK, "{body:?}");
    let answer = json_of(&body);
    assert_eq!(answer["via"], "mail");
    assert_eq!(
        answer["invitation"]["attendees"][0]["partstat"],
        "TENTATIVE"
    );
    let lines = scenario.mails.lock().expect("trace").clone();
    assert!(lines.contains(&"__done__".to_string()), "{lines:?}");
    let sent = lines.join("\n");
    assert!(sent.contains("RCPT TO:<camille@studio-lilas.fr>"), "{sent}");
    assert!(sent.contains("METHOD:REPLY"), "{sent}");
    // La partie est en quoted-printable : `=` s'y écrit `=3D`.
    assert!(sent.contains("PARTSTAT=3DTENTATIVE"), "{sent}");
    assert!(sent.contains("text/calendar"), "{sent}");
    assert!(sent.contains("Subject:"), "{sent}");
}

#[tokio::test]
async fn a_resource_that_does_not_list_us_is_answered_by_mail() {
    // L'organisateur a réécrit la ressource depuis l'envoi du mail : notre
    // adresse n'y figure plus.
    const WITHOUT_US: &str = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\n\
         BEGIN:VEVENT\r\nUID:reunion-42\r\nSUMMARY:Revue de design\r\n\
         DTSTART;TZID=Europe/Paris:20261125T140000\r\n\
         ORGANIZER:mailto:camille@studio-lilas.fr\r\n\
         ATTENDEE:mailto:quelqu-un@ailleurs.fr\r\n\
         END:VEVENT\r\nEND:VCALENDAR\r\n";
    let Some(scenario) = Scenario::open_calendar(message(), Some(WITHOUT_US)).await else {
        return;
    };

    let (status, body) = call(&scenario.state, rsvp("DECLINED")).await;

    assert_eq!(status, StatusCode::OK, "{body:?}");
    assert_eq!(json_of(&body)["via"], "mail");
    let sent = scenario.mails.lock().expect("trace").clone().join("\n");
    assert!(sent.contains("METHOD:REPLY"), "{sent}");
    assert!(sent.contains("PARTSTAT=3DDECLINED"), "{sent}");
    // Rien n'a été écrit dans la ressource : elle ne nous concerne pas.
    assert!(scenario
        .caldav
        .lock()
        .expect("trace")
        .iter()
        .all(|request| !request.starts_with("PUT ")));
}

#[tokio::test]
async fn a_cancel_has_nothing_to_answer() {
    let cancelled = message().replace("METHOD:REQUEST", "METHOD:CANCEL");
    let Some(scenario) = Scenario::open(cancelled, false).await else {
        return;
    };

    let (status, body) = call(&scenario.state, rsvp("ACCEPTED")).await;

    assert_eq!(status, StatusCode::BAD_REQUEST, "{body:?}");
    assert!(json_of(&body)["error"]
        .as_str()
        .unwrap_or_default()
        .contains("annulé"));
    assert!(!scenario
        .mails
        .lock()
        .expect("trace")
        .contains(&"__done__".to_string()));
}

#[tokio::test]
async fn an_unknown_answer_is_refused() {
    let Some(scenario) = Scenario::open(message(), true).await else {
        return;
    };

    let (status, body) = call(&scenario.state, rsvp("PEUT-ETRE")).await;

    assert_eq!(status, StatusCode::BAD_REQUEST, "{body:?}");
    assert_eq!(json_of(&body)["kind"], "calendar");
    // Rien n'a été écrit chez le serveur de calendrier.
    assert!(scenario.caldav.lock().expect("trace").is_empty());
}

#[tokio::test]
async fn the_invitation_of_an_unknown_message_is_a_404() {
    let Some(scenario) = Scenario::open(message(), false).await else {
        return;
    };

    let (status, _) = call(
        &scenario.state,
        get("/api/accounts/perso/folders/INBOX/messages/9/invitation"),
    )
    .await;

    assert_eq!(status, StatusCode::NOT_FOUND);
}
